<script>
const DOCS = __DOCS__;
const SEARCH = __SEARCH__;
const FILES = __FILES__;
const REPOSITORY_INDEX_URL = __REPOSITORY_INDEX_URL__;
const REPOSITORY_URL = 'https://github.com/arbabtalha/Costume-instructions';

const HOME = `
